  #[allow(clippy::clone_on_copy)]
  #[allow(clippy::vec_init_then_push)]
  pub fn invoke_signed(&self, signers_seeds: &[&[&[u8]]]) -> solana_program_error::ProgramResult {
          let args = PopulateClaimInputBufferInstructionArgs {
                                                              offset: self.instruction.offset.clone().expect("offset is not set"),
                                                                  rescue_encryption_public_key: self.instruction.rescue_encryption_public_key.clone().expect("rescue_encryption_public_key is not set"),
                                                                  encryption_nonce: self.instruction.encryption_nonce.clone().expect("encryption_nonce is not set"),
                                                                  rescue_encrypted_total_amount_ciphertext: self.instruction.rescue_encrypted_total_amount_ciphertext.clone().expect("rescue_encrypted_total_amount_ciphertext is not set"),
                                                                  rescue_encrypted_relayer_commission_fee_ciphertext: self.instruction.rescue_encrypted_relayer_commission_fee_ciphertext.clone().expect("rescue_encrypted_relayer_commission_fee_ciphertext is not set"),
                                                                  rescue_encrypted_protocol_commission_fee_ciphertext: self.instruction.rescue_encrypted_protocol_commission_fee_ciphertext.clone().expect("rescue_encrypted_protocol_commission_fee_ciphertext is not set"),
                                                                  encrypted_master_viewing_key: self.instruction.encrypted_master_viewing_key.clone().expect("encrypted_master_viewing_key is not set"),
                                                                  rescue_encrypted_lottery_ticket_delta: self.instruction.rescue_encrypted_lottery_ticket_delta.clone().expect("rescue_encrypted_lottery_ticket_delta is not set"),
                                                                  rescue_encrypted_random_blinding_factor_ciphertext: self.instruction.rescue_encrypted_random_blinding_factor_ciphertext.clone().expect("rescue_encrypted_random_blinding_factor_ciphertext is not set"),
                                                                  rescue_encryption_commitment: self.instruction.rescue_encryption_commitment.clone().expect("rescue_encryption_commitment is not set"),
                                                                  encryption_validation_polynomial: self.instruction.encryption_validation_polynomial.clone().expect("encryption_validation_polynomial is not set"),
                                                                  merkle_root: self.instruction.merkle_root.clone().expect("merkle_root is not set"),
                                                                  total_relayer_fees: self.instruction.total_relayer_fees.clone().expect("total_relayer_fees is not set"),
                                                                  transaction_viewing_key_timestamp: self.instruction.transaction_viewing_key_timestamp.clone().expect("transaction_viewing_key_timestamp is not set"),
                                                                  groth16_proof_a: self.instruction.groth16_proof_a.clone().expect("groth16_proof_a is not set"),
                                                                  groth16_proof_b: self.instruction.groth16_proof_b.clone().expect("groth16_proof_b is not set"),
                                                                  groth16_proof_c: self.instruction.groth16_proof_c.clone().expect("groth16_proof_c is not set"),
                                                                  optional_data: self.instruction.optional_data.clone().expect("optional_data is not set"),
                                                                  destination_program: self.instruction.destination_program.clone().expect("destination_program is not set"),
                                                                  cpi_account1: self.instruction.cpi_account1.clone().expect("cpi_account1 is not set"),
                                    };
        let instruction = PopulateClaimInputBufferCpi {
        __program: self.instruction.__program,
                  
          relayer: self.instruction.relayer.expect("relayer is not set"),
                  
          claim_input_buffer: self.instruction.claim_input_buffer.expect("claim_input_buffer is not set"),
                  
          system_program: self.instruction.system_program.expect("system_program is not set"),
                          __args: args,
            };
    instruction.invoke_signed_with_remaining_accounts(signers_seeds, &self.instruction.__remaining_accounts)
  }
